CREATE TABLE IF NOT EXISTS locations(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE COLLATE NOCASE,address TEXT NOT NULL,archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)));
CREATE TABLE IF NOT EXISTS facilities(id INTEGER PRIMARY KEY,location_id INTEGER NOT NULL REFERENCES locations(id),code TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN('Sumur','Pompa','Reservoir','Jaringan Distribusi')),capacity INTEGER NOT NULL CHECK(capacity>0),unit TEXT NOT NULL,description TEXT NOT NULL,archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)));
CREATE TABLE IF NOT EXISTS inspections(id INTEGER PRIMARY KEY,facility_id INTEGER NOT NULL REFERENCES facilities(id),on_date TEXT NOT NULL,condition TEXT NOT NULL CHECK(condition IN('Beroperasi','Terbatas','Tidak Beroperasi')),note TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS incidents(id INTEGER PRIMARY KEY,facility_id INTEGER NOT NULL REFERENCES facilities(id),on_date TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN('Ringan','Sedang','Berat')),description TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS repairs(id INTEGER PRIMARY KEY,incident_id INTEGER NOT NULL REFERENCES incidents(id),on_date TEXT NOT NULL,progress INTEGER NOT NULL CHECK(progress BETWEEN 0 AND 100),note TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS jobs(id INTEGER PRIMARY KEY,facility_id INTEGER NOT NULL REFERENCES facilities(id),starts_on TEXT NOT NULL,target_on TEXT NOT NULL,task TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('Direncanakan','Berlangsung','Selesai','Dibatalkan')),completed_on TEXT NOT NULL,CHECK(target_on>=starts_on));
CREATE TABLE IF NOT EXISTS job_events(id INTEGER PRIMARY KEY,job_id INTEGER NOT NULL REFERENCES jobs(id),status TEXT NOT NULL,task TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),recorded_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%SZ','now')));
